87	    @Mapping(target = "id", ignore = true)
88	    @Mapping(target = "pets", ignore = true)
89	    @Mapping(target = "customerCode", ignore = true)
90	    @Mapping(target = "householdId", ignore = true)
91	    @Mapping(target = "namesakeCount", ignore = true)
92	    @Mapping(target = "householdMemberCount", ignore = true)
93	    Owner toOwner(OwnerFieldsDto ownerDto);
94	
95	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
96	
97	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
