package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.function.owner.InvalidPostcodeException;

public class InvalidPostcodeExceptionHandler {

    public void handle(@Parameter InvalidPostcodeException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
                "The postcode must be four digits and within the valid range for the city's region "
                        + "(NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)");
        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
    }
}
```

### Wiring / config YAML (not Java, but part of the pipeline)
- `/home/daniel/sandbox/src/main/resources/officefloor/rest/api/owners.POST.yml` — the `validatePostcode` step runs `ValidateOwnerPostcode` early in the POST pipeline (after `validate`, before telephone normalization).
- `/home/daniel/sandbox/src/main/resources/officefloor/escalation/org.springframework.samples.petclinic.rest.function.owner.InvalidPostcodeException.yml` — routes the exception to the handler:
  ```yaml
